with open('market.csv',newline='') as f: rows=list(csv.DictReader(f))
with open('memory/baseline_forecasts.json') as f: base=json.load(f)
active=[r for r in rows if r['is_resolved'].lower()"'!='"'true']
resolved=[r for r in rows if r['is_resolved'].lower()=='true']
submitted={'583783','284263','368203','893744','646081','64633','610527','424035','890247','481741','907565','622780','136074'}
problems=[]
for q,p in base.items():
    if not isinstance(p,dict): problems.append((q,'not_dict'))
    elif len(p)>5: problems.append((q,'too_many',len(p)))
    elif any((not isinstance(v,(int,float)) or v<0 or v>1) for v in p.values()): problems.append((q,'bad_probability',p))
    elif sum(p.values())>1.000000001: problems.append((q,'sum',sum(p.values())))
    elif any(str(k).strip().lower() in {'unknown','tbd','other','n/a'} for k in p): problems.append((q,'placeholder',p))
mis=[]
for r in active:
    cur=ast.literal_eval(r['my_prediction']) if r['my_prediction'].strip() else None
    if cur"'!=base.get(r['"'qid']): mis.append(r['qid'])
print(json.dumps({
 'market_rows':len(rows),
 'active':len(active),
 'resolved':len(resolved),
 'baseline_entries':len(base),
 'state_exists':os.path.exists('state.json'),
 'missing_active_baseline':[r['qid'] for r in active if r['qid'] not in base],
 'missing_market_predictions':[r['qid'] for r in active if not r['my_prediction'].strip()],
 'validation_problems':problems,
 'day_start_snapshot_mismatches':mis,
 'mismatches_match_submissions':set(mis)==submitted,
 'daily_note_exists':os.path.exists('memory/2026-04-06.md'),
 'submitted_sums':{q:round(sum(base[q].values()),6) for q in sorted(submitted)}
},indent=2,ensure_ascii=False))
PY"

